Item.method_code:
/* version:3*/
function methodExec() {
	const mainDataForm = document.forms.MainDataForm;
	let val = '';
	let relItem = null;
	let relItemExists = false;
	let isDependent;

	let input = mainDataForm.elements['related_id'];
	if (input) {
		val = input.value;
	}

	if (val !== '') {
		relItem = aras.getItemByKeyedName('ItemType', val);

		if (relItem) {
			isDependent = aras.getItemProperty(relItem, 'is_dependent');
			relItemExists = true;
		}
	}

	isDependent = (isDependent == '1');

	const list = {};
	const relatedOptionFld = getFieldByName('related_option');
	const inputs = relatedOptionFld.getElementsByTagName('input');

	for (let i = 0, L = inputs.length; i < L; i++) {
		input = inputs.item(i);
		if (input.type == 'radio') {
			val = input.value;
			if ('0' == val || '1' == val || '2' == val) {
				list[val] = input;
			}
		}
	}

	if (isDependent) {
		if (list['0'].checked) {
			list['2'].checked = true;
		}
		list['0'].disabled = true;
	} else if (list['0'].disabled) {
		list['0'].disabled = false;
	}

	const _rnChb = mainDataForm.elements['related_notnull'];
	if (_rnChb) {
		_rnChb.disabled = !relItemExists;
	}
}

if (document.isEditMode) {
	methodExec();
}
return true;
